/* Shared field rules, including dynamically mounted dependent/financial forms. */
(function(root){
'use strict';
const digits=v=>String(v||'').replace(/\D/g,'');
function cpfMask(v){const d=digits(v).slice(0,11);return d.slice(0,3)+(d.length>3?'.'+d.slice(3,6):'')+(d.length>6?'.'+d.slice(6,9):'')+(d.length>9?'-'+d.slice(9):'')}
function cpfValid(v){const d=digits(v);if(d.length!==11||/^(\d)\1{10}$/.test(d))return false;for(let n=9;n<=10;n++){let sum=0;for(let i=0;i<n;i++)sum+=Number(d[i])*(n+1-i);const check=(sum*10)%11%10;if(check!==Number(d[n]))return false}return true}
function dateValid(v){const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(v);if(!m||+m[1]<1||+m[2]<1||+m[2]>12)return false;const y=+m[1],month=+m[2],day=+m[3],leap=y%4===0&&(y%100!==0||y%400===0);return day>=1&&day<=[31,leap?29:28,31,30,31,30,31,31,30,31,30,31][month-1]}
function moneyMask(v){const d=digits(v).replace(/^0+(?=\d)/,'').slice(0,15);if(!d)return '';const n=d.padStart(3,'0');return 'R$ '+n.slice(0,-2).replace(/\B(?=(\d{3})+(?!\d))/g,'.')+','+n.slice(-2)}
function moneyNumber(v){return v?Number(String(v).replace(/R\$|\s|\./g,'').replace(',','.')):0}
const api={cpfMask,cpfValid,dateValid,moneyMask,moneyNumber};if(typeof module!=='undefined')module.exports=api;if(!root.document)return;root.CicluzFieldRules=api;
const marked=new WeakSet();
function kind(el){if(el.type==='date')return 'date';if(/year|(^|-)ano($|-)/i.test(el.id)||/^\s*Ano de referência/i.test(el.closest('label')?.textContent||''))return 'year';if(['checkbox','radio','file','color','range','hidden'].includes(el.type))return '';const text=[el.name,el.id,el.getAttribute('aria-label'),el.closest('label')?.textContent,el.labels?.[0]?.textContent].join(' ');if(/\bcpf\b/i.test(text))return 'cpf';if(el.dataset.money==='true'||el.placeholder?.includes('R$')||/R\$|salário|salario/i.test(el.getAttribute('aria-label')||'')||/^\s*Valor(?:\s|$)/i.test(el.closest('label')?.textContent||''))return 'money';return ''}
function validate(el){const k=kind(el);if(!k||k==='money'||el.disabled||el.readOnly)return true;let msg='';if(el.value){if(k==='year'&&!/^[0-9]{4}$/.test(el.value))msg='Informe um ano com quatro dígitos.';if(k==='cpf'&&!cpfValid(el.value))msg='Informe um CPF válido com 11 dígitos.';if(k==='date'&&!dateValid(el.value))msg='Informe uma data válida, com ano de quatro dígitos.'}else if(k==='date'&&el.validity.badInput)msg='Informe dia, mês e ano de quatro dígitos.';el.setCustomValidity(msg);if(msg)el.setAttribute('aria-invalid','true');else el.removeAttribute('aria-invalid');return !msg}
function prepare(el){if(marked.has(el)||el.readOnly)return;const k=kind(el);if(!k)return;marked.add(el);if(k==='money'){el.dataset.money='true';el.type='text';el.inputMode='numeric';if(el.value&&!el.value.includes('R$'))el.value=moneyMask(String(Math.round(Number(el.value.replace(',','.'))*100)));el.maxLength=24;return}if(k==='year'){el.min='1';el.max='9999';el.step='1';el.inputMode='numeric';return}if(k==='date'){if(!el.min)el.min='0001-01-01';if(!el.max||el.max>'9999-12-31')el.max='9999-12-31'}else{el.inputMode='numeric';el.maxLength=14;el.pattern='[0-9]{3}\\.[0-9]{3}\\.[0-9]{3}-[0-9]{2}';if(!el.placeholder)el.placeholder='000.000.000-00'}validate(el)}
function selectArrow(el){const color=getComputedStyle(el).getPropertyValue('--ui-control-accent').trim()||'#7c3aed';if(el.dataset.arrowColor===color)return;el.dataset.arrowColor=color;for(const [key,path]of [['down','m6 9 6 6 6-6'],['up','m6 15 6-6 6 6']]){const svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="'+color+'" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="'+path+'"/></svg>';el.style.setProperty('--ui-select-'+key,'url("data:image/svg+xml,'+encodeURIComponent(svg)+'")')}}
function scan(){document.querySelectorAll('input').forEach(prepare);document.querySelectorAll('select').forEach(selectArrow)}
document.addEventListener('input',e=>{const el=e.target;if(!(el instanceof HTMLInputElement))return;prepare(el);const k=kind(el);if(k==='year')el.value=digits(el.value).slice(0,4);if(k==='money'){el.value=moneyMask(el.value);el.setSelectionRange(el.value.length,el.value.length);return}if(k==='cpf'){const cursor=el.selectionStart,n=digits(el.value.slice(0,cursor)).length;el.value=cpfMask(el.value);let p=0,count=0;while(p<el.value.length&&count<n){if(/\d/.test(el.value[p]))count++;p++}el.setSelectionRange(p,p)}if(k==='date'&&/^\d{5,}-/.test(el.value))el.value=el.value.replace(/^(\d{4})\d+(-)/,'$1$2');validate(el)});
document.addEventListener('change',e=>{if(e.target instanceof HTMLInputElement)validate(e.target)});
document.addEventListener('focusout',e=>{if(e.target instanceof HTMLInputElement)validate(e.target)});
function invalidIn(scope){const fields=[...scope.querySelectorAll('input,select,textarea')].filter(el=>!el.disabled&&!el.readOnly&&el.getClientRects().length);for(const el of fields){if(el instanceof HTMLInputElement)validate(el);if(!el.checkValidity()){el.reportValidity();return true}}return false}
document.addEventListener('submit',e=>{if(invalidIn(e.target)){e.preventDefault();e.stopImmediatePropagation()}},true);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!/^salvar\b|^concluir\b/i.test(b.textContent.trim()))return;const scope=b.closest('form,dialog,.view,.modal');if(scope&&invalidIn(scope)){e.preventDefault();e.stopImmediatePropagation()}},true);
new MutationObserver(records=>{if(records.some(r=>r.type==='childList'||r.target.tagName!=='SELECT'))scan()}).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['class','style']});scan();
})(typeof window!=='undefined'?window:globalThis);
